INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(371700, 0, 3717, 0, 0, 8, 'The Slave Pens', 'The Slave Pens lie beneath Serpent Lake in Coilfang Reservoir, a maze of flooded tunnels where the naga keep their slaves. Wastewalker Broken toil here as workers under Coilfang slavehandlers, who slap them and berate them for slacking off, while captives held apart in the pens call for help and asking how anyone can just leave them there. Not every Broken is a captive: Coilfang collaborators stand armed among the naga. Naga technicians, defenders, enchantresses and soothsayers hold the tunnels, observers patrol with rays at heel, and bogstroks swarm the shallows. Three masters stand out. Mennu the Betrayer, himself a Broken, fights for the naga; Rokmar the Crackler, a bogstrok of monstrous size, holds a stretch of the pens; and deep within, a fungal giant called Quagmirran keeps its lair. Somewhere in the reservoir, too, are the druids the Cenarion Expedition is still waiting for.', 'zones/slave_pens.txt (map 547: area 3717 only); DB spawns map 547: Wastewalker Slave 17963, Worker 17964, Captive 18206 (Broken models); Coilfang Slavehandler 17959, Collaborator 17962 (Broken model, faction 51), Technician 17940, Defender 17958, Enchantress 17961, Soothsayer 17960, Observer 17938 with Coilfang Ray 21128 (Observer''s Pet); Bogstrok 17816, Greater Bogstrok 17817; bosses 17941, 17991 (lobstrok model), 17942 (fungal giant model); smart_scripts 17959 (out of combat: Slap! on the workers and creature_text group 0: Too soon! You are slacking off too soon!; Wake up! Now get up and back to work!), 18206 (out of combat: Help me! Please help me!; How can you just leave me here?); zangarmarsh.json 352122 (Watcher Jhang waits at the entrance for four companions who went on inside)'),
(371701, 2, 3717, 1, 0, 8, 'Mennu the Betrayer', 'Mennu the Betrayer is a Broken, and he fights for the naga of Coilfang in the Slave Pens while others of his kind toil around him as slaves. His name says all that anyone is told of how he came to be there. He is a shaman, and he has kept the craft for his new masters: he sets down totems that bind his foes in grasping earth, harden his own skin against their blows and burst in searing novas, raises a ward to heal himself when hard pressed, and strikes at those who come for him with bolts of lightning.', 'creature_template 17941 (faction 74, the Coilfang naga''s faction) and display 17728 (BrokenMale); boss_mennu_the_betrayer.cpp (Lightning Bolt; Earthgrab, Stoneskin and Nova totems; Healing Ward at 60 percent health); warcraft.wiki.gg/wiki/Mennu_the_Betrayer (Broken shaman)'),
(371702, 2, 3717, 2, 0, 8, 'Quagmirran', 'Quagmirran is a fungal giant, and it keeps a lair deep in the Slave Pens, past the naga and their slaves. It does not wait to be found. When intruders step into its lair, the giant stirs and comes lumbering out along its path to meet them. It fights with crushing blows, cleaving at those before it and hurling them back with great uppercuts, and it fouls the air around it, spraying acid on one foe after another and loosing volleys of poison bolts over all who stand near.', 'creature_template 17942 (display 18224, FungalGiant model); the_slave_pens.cpp (at_quagmirran_lair: entering the lair sends Quagmirran along its waypoint path); boss_quagmirran.cpp (Cleave, Uppercut, Acid Spray, Poison Bolt Volley)'),
(371703, 3, 3717, 1, 0, 8, 'Lost in Action', 'At the entrance to Coilfang Reservoir, Watcher Jhang begs for help. Ysiel Windsinger sent her and four companions to investigate the mystery of the steam pumps and why they are being used to drain the marsh, but her friends split up and went on recklessly without her. Those four can be such jerks sometimes, she says, but she loves them anyway, and she fears the worst. Their names are Earthbinder Rayge, Naturalist Bite, Weeder Greenthumb and Windcaller Claw, and they are to be sought in both the Slave Pens and the Underbog.', 'quest 9738 description and log text (Watcher Jhang 17884 starts and ends it at the entrance on map 530; QuestType 2, Flags 136; QuestSortID 3905; credits 17885, 17893, 17890, 17894); creature_model_info 17294 (Jhang''s display, female); smart_scripts 17827 (Claw gives the 17894 credit) and 17885 (Rayge''s credit); zangarmarsh.json 352122 and 352135 (Jhang at the entrance; 9876 leaves 9738 for the Coilfang files)'),
(371704, 3, 3717, 2, 0, 8, 'The Cudgel of Kar''desh', 'In a cell in the Slave Pens the naga keep a prisoner of their own kind: Skar''this the Heretic. He has nothing but hatred for his jailers. Burn it all down, he rages: they deserve nothing, and they must pay for what they have done and for what they continue to do. He would kill Lady Vashj himself if he could break free of these bindings. Perhaps, he suggests to the soft-skin before him, they seek to do the work of Neptulon; either way her death serves them both, and together they might form the sacred cudgel.', 'quest 10900 The Mark of Vashj reward text (Burn it down, $R ... I would kill Vashj myself if I could break free of these damned bindings. Or maybe you seek to do the work of Neptulon? Her death serves both of us, soft-skin. Will you assist me in forming the sacred cudgel.); creature_template 22421 Skar''this the Heretic (display 20990, Naga_Male; faction 1194; spawnMask 2, map 547 only), gameobject 185292 Skar''this''s Prison beside him; creature_queststarter/questender 22421: 10900 and 13431 (base); mod-individual-progression dungeon_attunements.sql gives 22421 quest 10901 instead of 13431 and lifts its disable; warcraft.wiki.gg/wiki/Skar''this_the_Heretic (naga, servant of Neptulon)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(371701, 1, 0, 255, 'For all his totems and his lightning, Mennu fell in the Slave Pens, struck down among the naga he served while Broken slaves toiled around him. Whatever had turned him against his own people, he took the answer with him.', 'boss_mennu_the_betrayer.cpp (fixed spawn 79362, map 547 only)'),
(371702, 1, 0, 255, 'Not everyone believes Quagmirran is real. Naturalist Bite came into the Slave Pens to prove the existence of the giant, most mythical of fungal giants, and ended up shut in a naga cage not far from its lair. He got his wish, he admits, sort of.', 'npc_text 9119 (gossip 7520: I came in here to prove the existence of Quagmirran, that most mythical of fungal giants. I got my wish, sort of.)'),
(371702, 2, 0, 255, 'Quagmirran came lumbering out to meet its killers and died in the Slave Pens, for all its crushing blows, its acid and its poison. The fungal giant that kept its lair past the naga and their slaves would trouble no one again.', 'boss_quagmirran.cpp (fixed spawn 80260, map 547 only)'),
(371703, 1, 0, 255, 'Weeder Greenthumb did not make it out. His remains lie in the Slave Pens, where by all appearances he was killed quick and clean while trying to make his escape, one of Jhang''s companions who would not be coming back.', 'npc_text 9118 (gossip 7519: the remains of Weeder Greenthumb; killed quick and clean while trying to make his escape from the Slave Pens); smart_scripts 17890 (gossip hello gives the Lost in Action credit)'),
(371703, 2, 0, 255, 'Naturalist Bite was found alive, locked in a naga cage deep in the Slave Pens and shouting for attention from inside it. He almost made it, he says. He came to prove that the fungal giant Quagmirran exists, and now he wants out, offering a boon in return for his freedom.', 'creature_text 17893 group 0 (Hey! Over here! ... I''m in this cage!!!); npc_text 9119 (I almost made it! ... You must let me free! In return I will grant you a boon); gameobject 182094 Cage (map 547) beside him'),
(371703, 3, 0, 255, 'Jhang was glad that some of her friends yet lived, though what had befallen the others broke her heart. At least, she sighed, they had died doing what they loved most in life, and she pressed a token of her eternal gratitude on the one who had brought her word.', 'quest 9738 reward text (glad that some of my friends yet live, but it breaks my heart to hear of the fate of others; at least they died doing what they loved most in life; eternal gratitude)'),
(371704, 1, 0, 255, 'The cudgel of Kar''desh needs two elemental signets. The earthen signet is held by Gruul the Dragonkiller in his lair in the Blade''s Edge Mountains. The other, the blazing signet, is the burning heart of Nightbane, a mythical beast said to dwell in the hallowed halls of the prophet Medivh.', 'quests 10901 and 13431 description (identical: the earthen signet held by Gruul the Dragonkiller in his lair in the Blade''s Edge Mountains; the blazing heart of Nightbane in the hallowed halls of the prophet, Medivh)'),
(371704, 2, 0, 255, 'With both signets in his hands, Skar''this swore that the reformed cudgel would break his bonds, and that he would return to Serpentshrine to take vengeance on Vashj and her minions. He had not forgotten their agreement, he said: his ally, too, would now be able to enter the lair of Lady Vashj.', 'quest 10901 completion text (With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!) and reward text (I have not forgotten our agreement, mortal. You too will now be able to enter the lair of Lady Vashj.)'),
(371704, 3, 0, 255, 'With both signets in his hands, Skar''this swore that the reformed cudgel would break his bonds, and that he would return to Serpentshrine to take vengeance on Vashj and her minions. At last, he said: with his bonds broken and the cudgel his, he would send the sea witch back to the icy depths.', 'quest 13431 completion text (same as 10901) and reward text (With these bonds broken and the cudgel in my possession I shall send the sea witch back to the icy depths...)');
